<script lang="ts">
    /**
     * Inline phosphor icon in the current text colour.
     *
     * Args:
     *   name: which icon to draw.
     *   size: width and height in `em`, default 1.1.
     */
    let { name, size = 1.1 }: { name: IconName; size?: number } = $props();
</script>

<svg
    width="{size}em"
    height="{size}em"
    viewBox="0 0 256 256"
    fill="currentColor"
    aria-hidden="true"
>
    {@html shapes[name]}
</svg>

<style>
    svg {
        flex: none;
    }
</style>
